'use strict';

/* Sprites dos monstros.
 *
 * Diferente das torres, o quadro NAO vem de um cooldown: vem da distancia
 * percorrida, entao o passo acompanha a velocidade. Um Veloz anda o dobro
 * mais rapido e pisa o dobro mais rapido, sem nenhum timer separado.
 *
 * Alinhamento em duas partes, as duas necessarias:
 *
 *   CENTRO  pelo centroide da massa de pixels, nao pela caixa delimitadora.
 *           A caixa cresce e encolhe quando arma e bracos balancam; o
 *           centroide e dominado pelo torso e fica quieto.
 *
 *   ESCALA  a janela de recorte de cada quadro e proporcional ao corpo
 *           daquele quadro, entao depois do resize todos saem do mesmo
 *           tamanho. Sem isso o Tanque pulsava 12,8% entre os dois passos,
 *           porque a maca de corrente muda muito a area visivel.
 *
 * bodyRatio    diametro do corpo dividido pelo lado do sprite. O motor
 *              desenha com lado (raio*2 / bodyRatio), entao arma e bracos
 *              passam para fora do circulo de colisao, como deve ser.
 *
 * angleOffset  a arte anda para BAIXO no quadro; o angulo 0 do jogo aponta
 *              para a direita.
 */

const MOBS = {
  /* guerreiro de elmo e manto vermelho, tres passos */
  grunt: {
    bodyRatio: 0.5555,
    angleOffset: -Math.PI / 2,
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  /* goblin magro de adaga, dois passos */
  veloz: {
    bodyRatio: 0.4583,
    angleOffset: -Math.PI / 2,
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  /* cavaleiro blindado com maca de corrente e escudo, dois passos */
  tanque: {
    bodyRatio: 0.5717,
    angleOffset: -Math.PI / 2,
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  /* conjurador encapuzado de manto vermelho e orbe roxo, dois passos */
  bruxo: {
    bodyRatio: 0.5546,
    angleOffset: -Math.PI / 2,
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  }
};

/* Os afixos recolorem o sprite. Pre-tingir uma vez no carregamento e muito
 * mais barato que compor por inimigo a cada quadro -- numa onda cheia sao
 * dezenas de inimigos a 60fps. */
const MobSheet = {
  load() {
    for (const key of Object.keys(MOBS)) {
      const set = MOBS[key];
      set.tinted = {};
      set.images = set.frames.map(src => {
        const img = new Image();
        img.onload = () => {
          set.loaded = (set.loaded || 0) + 1;
          if (set.loaded === set.frames.length) this.buildTints(key);
        };
        img.src = src;
        return img;
      });
    }
  },

  buildTints(key) {
    const set = MOBS[key];
    const size = set.images[0].naturalWidth || 160;

    for (const affixKey of Object.keys(AFFIXES)) {
      const color = AFFIXES[affixKey].color;
      set.tinted[affixKey] = set.images.map(img => {
        if (!color) return img;              // 'comum' usa a arte original
        const cv = document.createElement('canvas');
        cv.width = cv.height = size;
        const c = cv.getContext('2d');
        c.drawImage(img, 0, 0, size, size);
        // 0.42 lavava o sprite e apagava a textura da armadura; 0.30 desloca
        // o tom o bastante para o afixo ler e ainda deixa a arte aparecer.
        c.globalCompositeOperation = 'source-atop';
        c.globalAlpha = 0.30;
        c.fillStyle = color;
        c.fillRect(0, 0, size, size);
        return cv;
      });
    }
    set.ready = true;
  },

  get(key) {
    const set = MOBS[key];
    return set && set.ready ? set : null;
  },

  /* Quadro do passo a partir da distancia percorrida. */
  frameFor(set, enemy) {
    const stride = enemy.radius * 1.15;
    const i = Math.floor(enemy.walked / stride) % set.frames.length;
    return i < 0 ? 0 : i;
  }
};
